def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: datetime.timedelta instance
    :type value: datetime.timedelta
    :return: float representing the total number of seconds, or None if the input is invalid
    """
    if value is None:
        return None
    try:
        seconds = value.total_seconds()
    except AttributeError:
        # value does not have a total_seconds method, so it is not a timedelta
        return None
    # Ensure the result is a plain number (int or float) that can be JSON‑serialised
    try:
        return float(seconds)
    except Exception:
        return None

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except AttributeError:
        raise TypeError(
            "value must be a datetime.time instance, got %r" % type(value)
        )
    except Exception as exc:
        raise ValueError("Failed to dehydrate time value: %s" % exc) from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        lat = getattr(value, "lat")
        lon = getattr(value, "lon")
        time = getattr(value, "time")
    except AttributeError as exc:
        raise TypeError("value must have 'lat', 'lon', and 'time' attributes") from exc

    if not isinstance(lat, (int, float)):
        raise TypeError(f"lat must be a number, got {type(lat).__name__}")
    if not isinstance(lon, (int, float)):
        raise TypeError(f"lon must be a number, got {type(lon).__name__}")

    if hasattr(time, "isoformat"):
        time_str = time.isoformat()
    elif isinstance(time, str):
        time_str = time
    else:
        raise TypeError(f"time must be a datetime or ISO string, got {type(time).__name__}")

    return {"lat": lat, "lon": lon, "time": time_str}

def keys(self):
    """
    Return the keys of the record.
    :return: list of key names
    """
    try:
        if hasattr(self, "_keys") and isinstance(self._keys, dict):
            return list(self._keys.keys())
        return []
    except Exception:
        return []

def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    def decorator(func):
        def wrapper(session, *args, **kwargs):
            if session is None:
                raise ValueError("session must be provided")
            tx_config = {}
            if metadata is not None:
                if not isinstance(metadata, dict):
                    raise TypeError("metadata must be a dict")
                tx_config["metadata"] = metadata
            if timeout is not None:
                if not isinstance(timeout, (int, float)):
                    raise TypeError("timeout must be a number or None")
                if timeout < 0:
                    raise ValueError("timeout must not be negative")
                tx_config["timeout"] = timeout
            try:
                with session.begin_transaction(**tx_config) as tx:
                    return func(tx, *args, **kwargs)
            except Exception as e:
                # Optionally log the exception here
                raise
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError(f"Key not found: {key}") from None

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to get all values
    def _all_values():
        try:
            # If the object behaves like a dict
            return [v for _, v in self.items()]
        except AttributeError:
            # Fallback to a list of (key, value) tuples
            try:
                return [v for _, v in self._items]
            except Exception:
                # As a last resort, try iterating over the object itself
                return list(self)

    if not keys:
        return _all_values()

    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as an index into the underlying list of items
            try:
                result.append(self._items[key][1])
            except (IndexError, AttributeError):
                raise IndexError(f"Index {key} out of range")
        else:
            # Treat as a key lookup
            try:
                result.append(self[key])
            except KeyError:
                # Try a dict-like get method
                try:
                    val = self.get(key)
                    if val is None:
                        raise KeyError
                    result.append(val)
                except Exception:
                    raise KeyError(f"Key {key} not found")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the mapping from field names to indices
    if isinstance(self._keys, dict):
        name_to_index = self._keys
        index_to_name = {idx: name for name, idx in name_to_index.items()}
    else:
        # Assume list or tuple of field names
        name_to_index = {name: idx for idx, name in enumerate(self._keys)}
        index_to_name = {idx: name for idx, name in enumerate(self._keys)}

    # If no keys specified, return all fields
    if not keys:
        return {name: self._values[idx] for name, idx in name_to_index.items()}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Handle negative indices
            if key < -len(self._values) or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds for record of length {len(self._values)}")
            idx = key
            name = index_to_name.get(idx, None)
            if name is None:
                # This should not happen if mapping is consistent
                name = f"field_{idx}"
            result[name] = self._values[idx]
        elif isinstance(key, str):
            if key in name_to_index:
                idx = name_to_index[key]
                result[key] = self._values[idx]
            else:
                result[key] = None
        else:
            raise TypeError(f"Unsupported key type {type(key).__name__}; expected int or str")
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the object has a data attribute
    if not hasattr(self, 'data'):
        raise AttributeError("The object does not have a 'data' attribute.")
    # Ensure there are at least two bytes to pop
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop 2 bytes.")
    # Retrieve the last two bytes
    try:
        last_two = self.data[-2:]
    except Exception as exc:
        raise ValueError(f"Failed to access last two bytes: {exc}") from exc
    # Remove the last two bytes from the data buffer
    if isinstance(self.data, bytearray):
        del self.data[-2:]
    else:
        # For immutable types like bytes, create a new slice
        self.data = self.data[:-2]
    # Convert the two bytes to an unsigned integer (big-endian)
    return int.from_bytes(last_two, byteorder='big', signed=False)

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate input types
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(qid, int):
        raise TypeError("qid must be an integer")
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict or None")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict or None")

    # Construct the DISCARD message
    message = {"type": "DISCARD", "n": n, "qid": qid}

    # Apply dehydration hooks to any values that match the hook types
    if dehydration_hooks:
        for typ, func in dehydration_hooks.items():
            for key, value in list(message.items()):
                if isinstance(value, typ):
                    try:
                        message[key] = func(value)
                    except Exception as exc:
                        raise ValueError(
                            f"Dehydration hook for {typ} failed: {exc}"
                        ) from exc

    # Append the message to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        raise AttributeError(
            "The object does not have an '_output_queue' attribute"
        )
    except Exception as exc:
        raise RuntimeError(
            f"Failed to append message to output queue: {exc}"
        ) from exc

    # Create and return a Response object
    try:
        response = Response(
            message,
            dehydration_hooks=dehydration_hooks,
            hydration_hooks=hydration_hooks,
            **handlers
        )
    except Exception as exc:
        raise RuntimeError(
            f"Failed to create Response object: {exc}"
        ) from exc

    return response

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")
    # Validate bookmarks
    if bookmarks is not None:
        try:
            bookmarks = list(bookmarks)
        except TypeError:
            raise ValueError("bookmarks must be an iterable")
    # Validate metadata
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dict")
    # Validate timeout
    if timeout is not None and not isinstance(timeout, (int, float)):
        raise ValueError("timeout must be a number")
    # Validate db
    if db is not None and not isinstance(db, str):
        raise ValueError("db must be a string")
    # Validate imp_user
    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError("imp_user must be a string")
    # Validate hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dict")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dict")
    # Build payload
    payload = {}
    if mode is not None:
        payload["mode"] = mode
    if bookmarks:
        payload["bookmarks"] = bookmarks
    if metadata:
        payload["metadata"] = metadata
    if timeout is not None:
        payload["timeout"] = timeout
    if db is not None:
        payload["db"] = db
    if imp_user is not None:
        payload["imp_user"] = imp_user
    if dehydration_hooks:
        payload["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        payload["hydration_hooks"] = hydration_hooks
    # Append to output queue
    try:
        self._write_message("BEGIN", payload)
    except Exception as exc:
        raise RuntimeError(f"Failed to write BEGIN message: {exc}") from exc
    # Return a Response object, passing any handlers
    return Response(self, handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")
    # Validate fields iterable
    try:
        field_iter = iter(fields)
    except TypeError:
        raise TypeError("fields must be an iterable of field names")
    field_names = []
    for f in field_iter:
        if not isinstance(f, str) or not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        if f in field_names:
            raise TypeError(f"Duplicate field name: {f!r}")
        field_names.append(f)
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    # Build namespace for the new class
    namespace = {
        "__slots__": tuple(field_names),
        "SRID_MAP": srid_map,
    }
    # Optionally add a simple __repr__ that includes the fields
    def _repr(self):
        field_vals = ", ".join(f"{name}={getattr(self, name)!r}" for name in field_names)
        return f"{name}({field_vals})"
    namespace["__repr__"] = _repr
    # Create the new subclass of Point
    try:
        cls = type(name, (Point,), namespace)
    except Exception as exc:
        raise TypeError(f"Failed to create Point subclass {name!r}: {exc}") from exc
    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate input type
    if seq is None:
        raise TypeError("seq cannot be None")
    if not isinstance(seq, Sequence):
        raise TypeError(f"seq must be a Sequence, got {type(seq).__name__}")
    # Ensure all elements are strings
    for idx, item in enumerate(seq):
        if not isinstance(item, str):
            raise TypeError(f"Element at index {idx} is not a string (type {type(item).__name__})")
    # Convert to list for shuffling
    items = list(seq)
    # Compute a deterministic seed from the sequence content
    try:
        seed = hash(tuple(seq))
    except Exception as exc:
        raise RuntimeError("Failed to compute hash for deterministic shuffle") from exc
    # Perform deterministic shuffle using a local Random instance
    try:
        import random as _random
        rnd = _random.Random(seed)
        rnd.shuffle(items)
    except Exception as exc:
        raise RuntimeError("Error during deterministic shuffle") from exc
    return items

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize <= 0:
        raise ValueError("maxsize must be > 0")
    if ttl <= 0:
        raise ValueError("ttl must be > 0")
    if timer is None:
        timer = time.monotonic

    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a key from the arguments
            key = (args, tuple(sorted(kwargs.items())))
            if typed:
                key = (key,
                       tuple(type(v) for v in args),
                       tuple(type(v) for v in kwargs.values()))
            now = timer()
            if key in cache:
                value, expire = cache.pop(key)
                if expire > now:
                    # Cache hit – reinsert to mark as recently used
                    cache[key] = (value, expire)
                    return value
                # Expired entry – discard
            # Cache miss or expired
            result = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (result, expire)
            # Evict least-recently used if over maxsize
            if len(cache) > maxsize:
                # popitem(last=False) removes the first inserted item
                cache.popitem(last=False)
            return result
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        def make_key(args, kwargs, typed):
            if typed:
                # Include types of arguments in the key
                args_key = tuple((arg, type(arg)) for arg in args)
                kwargs_key = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
                return (args_key, kwargs_key)
            else:
                return (args, tuple(sorted(kwargs.items())))
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs, typed)
            if key in cache:
                # Move key to end to mark as most recently used
                value = cache.pop(key)
                cache[key] = value
                return value
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                # Evict the most recently used item (last inserted)
                last_key = next(reversed(cache))
                del cache[last_key]
            return result
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Get the first key in insertion order
        first_key = next(iter(self))
        # Retrieve and remove the value
        value = self.pop(first_key)
        return (first_key, value)
    except StopIteration:
        # The dictionary is empty
        raise KeyError('popitem(): dictionary is empty')

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    storage = self.storage
    try:
        if key in storage:
            return storage[key]
        storage[key] = default
        self.storage._p_changed = True
        return default
    except TypeError:
        logger.error(f"setdefault: Key {key!r} is not hashable")
        return None
    except Exception as e:
        logger.error(f"setdefault: Unexpected error for key {key!r}: {e}")
        return None

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key is not hashable
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        wrapper.__name__ = method.__name__
        wrapper.__doc__ = method.__doc__
        return wrapper
    return decorator

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    try:
        with open(file_name, encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """
    Reset
    """
    try:
        root = logging.getLogger()
        # Remove all existing handlers
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        # Reset the root logger level to WARNING
        root.setLevel(logging.WARNING)
        # Reconfigure basicConfig to default settings
        logging.basicConfig(level=logging.WARNING)
    except Exception as exc:
        # If logging is not configured, fall back to printing the error
        try:
            root = logging.getLogger()
            root.error("Failed to reset logging: %s", exc)
        except Exception:
            print(f"Failed to reset logging: {exc}")

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
        return _directlyProvidedBy(object)
    except Exception:
        # If the object is not a class or instance that zope.interface can handle,
        # return an empty declaration.
        from zope.interface.interfaces import IDeclaration
        return IDeclaration([])

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Convert to list to allow multiple passes
    try:
        classes_list = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects")

    # Validate elements
    for cls in classes_list:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class")

    # Build minimal set: keep a class only if no other class in the list is a subclass of it
    minimal = []
    for cls in classes_list:
        # Skip if already included (handle duplicates)
        if cls in minimal:
            continue
        # If any other class is a subclass of cls, cls is redundant
        if any(other is not cls and issubclass(other, cls) for other in classes_list):
            continue
        minimal.append(cls)

    return minimal

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    try:
        self.context = {}
    except AttributeError as exc:
        raise AttributeError("Histogram object has no 'context' attribute.") from exc

    # Reinitialize bins
    try:
        # If an initial value is defined, use it to fill the bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if not isinstance(self.initial_value, (int, float)):
                raise TypeError("initial_value must be numeric.")
            if hasattr(self, "bins"):
                # Preserve the existing bin structure if possible
                if isinstance(self.bins, list):
                    self.bins = [self.initial_value for _ in self.bins]
                else:
                    # Try to replace all elements in place
                    try:
                        self.bins[:] = [self.initial_value] * len(self.bins)
                    except Exception:
                        # Fallback: create a new list of the same length
                        self.bins = [self.initial_value] * len(self.bins)
            else:
                # No bins attribute yet – create a single-element list
                self.bins = [self.initial_value]
        else:
            # No initial value – use the make_bins method
            if not hasattr(self, "make_bins") or not callable(self.make_bins):
                raise AttributeError("Histogram object has no callable 'make_bins' method.")
            self.bins = self.make_bins()
    except Exception as exc:
        raise RuntimeError(f"Failed to reinitialize bins: {exc}") from exc

    # Optional: reset other bookkeeping attributes if they exist
    for attr in ("total_count", "min_value", "max_value"):
        if hasattr(self, attr):
            try:
                setattr(self, attr, 0 if attr == "total_count" else None)
            except Exception:
                pass

    return None

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate inputs
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []
    if header is not None:
        lines.append(header)

    # Determine iterable of points
    points = getattr(self, "points", None)
    if points is None:
        # Assume the object itself is iterable
        points = self

    for point in points:
        try:
            # Extract coordinate
            if hasattr(point, "coord"):
                coord = point.coord
            elif hasattr(point, "coordinate"):
                coord = point.coordinate
            elif isinstance(point, (list, tuple)):
                coord = point[0]
            else:
                coord = point

            # Extract value
            if hasattr(point, "value"):
                value = point.value
            elif hasattr(point, "data"):
                value = point.data
            elif isinstance(point, (list, tuple)):
                value = point[1] if len(point) > 1 else None
            else:
                value = None

            coord_str = str(coord)

            if value is None:
                value_parts = []
            elif isinstance(value, (list, tuple)):
                value_parts = [str(v) for v in value]
            else:
                value_parts = [str(value)]

            line = separator.join([coord_str] + value_parts)
            lines.append(line)
        except Exception as exc:
            # Skip problematic points but keep processing
            continue

    return "\n".join(lines)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Guard against None
    if seq is None:
        return False

    # Avoid treating strings or bytes as sequences
    if isinstance(seq, (str, bytes)):
        return False

    # If seq is a Source sequence, reject
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source not defined; skip check
        pass

    # If seq itself is a FillRequest, accept
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest not defined; skip check
        pass

    # If seq is iterable, check its elements
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    for item in iterator:
        try:
            if isinstance(item, FillRequest):
                return True
        except NameError:
            # If FillRequest not defined, cannot match
            continue

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
        return callable(run_attr)
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if weight is None:
        weight = 1
    if not np.isscalar(weight):
        raise TypeError("weight must be a scalar value")
    # Convert coord to array
    try:
        coord_arr = np.asarray(coord)
    except Exception as exc:
        raise TypeError("coord must be array-like") from exc
    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1-D array-like of length equal to histogram dimensions")
    # Ensure histogram attributes exist
    if not hasattr(self, "edges") or not hasattr(self, "bins"):
        raise AttributeError("Histogram object must have 'edges' and 'bins' attributes")
    # Check dimensionality
    if len(coord_arr) != len(self.edges):
        raise ValueError(f"coord length {len(coord_arr)} does not match histogram dimensions {len(self.edges)}")
    # Determine bin indices
    indices = []
    for dim, edge in enumerate(self.edges):
        # Find the rightmost bin index where coord <= edge
        idx = np.searchsorted(edge, coord_arr[dim], side='right') - 1
        # Check if coordinate is outside the bin edges
        if idx < 0 or idx >= len(edge) - 1:
            # Outside histogram bounds; ignore
            return
        indices.append(idx)
    # Increment the appropriate bin
    try:
        self.bins[tuple(indices)] += weight
    except Exception as exc:
        raise ValueError("Failed to add weight to histogram bin") from exc
    return None

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    for key, value in manifest_dict.items():
        # If the value is a dict, recurse
        if isinstance(value, dict):
            # For the top-level identifying fields, keep the original dict
            if first_level and key in ("apiVersion", "kind", "metadata"):
                result[key] = value
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # If the value is a list, process each element
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        # For all other types, replace with None
        else:
            if first_level and key in ("apiVersion", "kind", "metadata"):
                result[key] = value
            else:
                result[key] = None
    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type validation
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Ensure the manifest list is at least as long as the schema
    while len(last_applied_manifest) < len(observer_schema):
        last_applied_manifest.append(None)

    for idx, schema_item in enumerate(observer_schema):
        # Skip if the response does not contain this index
        if idx >= len(response):
            continue

        resp_val = response[idx]

        # If the schema item is a dict, we need to recurse into a dict
        if isinstance(schema_item, dict):
            # Ensure the corresponding entry in the manifest is a dict
            if not isinstance(last_applied_manifest[idx], dict):
                last_applied_manifest[idx] = {}
            # Recursively update the nested dict
            try:
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[idx], schema_item, resp_val
                )
            except Exception as exc:
                # If the nested update fails, log and continue
                # (Assuming a logger is available; otherwise ignore)
                try:
                    import logging

                    logging.getLogger(__name__).warning(
                        "Failed to update nested manifest at index %s: %s",
                        idx,
                        exc,
                    )
                except Exception:
                    pass
            continue

        # For scalar fields, set the value if it is not already present
        if last_applied_manifest[idx] is None:
            last_applied_manifest[idx] = resp_val
        # If the value is already present, we leave it unchanged (no overwrite)
    # The function mutates ``last_applied_manifest`` in place; no return value.

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If any of the arguments are not dicts

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.  Nested dictionaries are
    handled recursively.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    for key, sub_schema in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")

        # If the key is not yet in the manifest, initialise it
        if key not in last_applied_manifest:
            # If the schema indicates a nested dict, initialise an empty dict
            if isinstance(sub_schema, dict):
                last_applied_manifest[key] = {}
                # Recurse into the nested structure
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            else:
                # Leaf node: copy the value directly
                last_applied_manifest[key] = response[key]
        else:
            # If the key already exists and the schema is a dict, recurse
            if isinstance(sub_schema, dict) and isinstance(
                last_applied_manifest[key], dict
            ):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            # If the key exists but the schema is not a dict, we leave the
            # existing value untouched (it was already set earlier).

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Safely access the manifest list
        spec = getattr(app, "spec", None)
        if spec is None:
            return {}
        manifest = getattr(spec, "manifest", None)
        if not isinstance(manifest, list):
            return {}

        # Existing observer schemas
        observer_schema = getattr(spec, "observer_schema", {})
        if not isinstance(observer_schema, dict):
            observer_schema = {}

        default_schemas = {}
        for resource in manifest:
            if not isinstance(resource, dict):
                continue
            kind = resource.get("kind")
            if not kind:
                continue
            # Skip if a custom schema already exists
            if kind in observer_schema:
                continue
            # Create a very permissive default schema
            default_schemas[kind] = {"type": "object"}
        return default_schemas
    except Exception:
        # In case of unexpected errors, return an empty dict
        return {}

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        p = os.path.abspath(str(path))
        if not os.path.exists(p):
            return False
        if not os.path.isdir(p):
            return False
        ocfl_version = os.path.join(p, '.ocfl_version')
        if not os.path.isfile(ocfl_version):
            return False
        try:
            with open(ocfl_version, 'r') as f:
                version = f.read().strip()
                if not version:
                    return False
        except Exception:
            return False
        objects_dir = os.path.join(p, 'objects')
        if not os.path.isdir(objects_dir):
            return False
        if not any(os.scandir(objects_dir)):
            return False
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = self.status
    if hasattr(status, 'name'):
        status_text = status.name
    else:
        status_text = str(status)
    return f"{prefix}{status_text}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Retrieve the log attribute; if it doesn't exist, return an empty string.
        log_entries = getattr(self, 'log', None)
        if log_entries is None:
            return ''
        # Ensure the log is an iterable of entries.
        if not isinstance(log_entries, (list, tuple)):
            raise TypeError("Expected 'log' to be a list or tuple of entries")
        # Build the string representation line by line.
        lines = []
        for entry in log_entries:
            # If the entry is a mapping, try to extract a human‑readable message.
            if isinstance(entry, dict):
                msg = entry.get('message', str(entry))
            else:
                msg = str(entry)
            lines.append(f"{prefix}{msg}")
        return "\n".join(lines)
    except Exception as exc:
        # Wrap any unexpected error in a RuntimeError to provide context.
        raise RuntimeError(f"Failed to generate status string: {exc}") from exc

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary, got %s" % type(inventory).__name__)

    # Extract spec version if requested
    if extract_spec_version:
        spec_type = inventory.get('type')
        if isinstance(spec_type, str):
            # Assume spec_type corresponds to a version string
            self.spec_version = spec_type
        else:
            # Keep existing spec_version
            pass

    # Validate required fields
    required = getattr(self, 'required_fields', [])
    missing = [field for field in required if field not in inventory]
    if missing:
        raise ValueError("Missing required inventory fields: %s" % ', '.join(missing))

    # Validate type
    if 'type' in inventory:
        if not isinstance(inventory['type'], str):
            raise ValueError("Inventory 'type' must be a string, got %s" % type(inventory['type']).__name__)
        allowed = getattr(self, 'allowed_types', None)
        if allowed and inventory['type'] not in allowed:
            raise ValueError("Unsupported inventory type '%s'. Allowed types: %s" % (inventory['type'], allowed))

    # Validate items if present
    if 'items' in inventory:
        items = inventory['items']
        if not isinstance(items, list):
            raise ValueError("Inventory 'items' must be a list, got %s" % type(items).__name__)
        if hasattr(self, 'validate_item'):
            for idx, item in enumerate(items):
                try:
                    self.validate_item(item)
                except Exception as e:
                    raise ValueError("Invalid item at index %d: %s" % (idx, e))

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    try:
        digests_set = set(digests_used)
    except TypeError:
        raise TypeError("digests_used must be an iterable of digests")

    missing = [fname for fname, digest in manifest_files.items() if digest not in digests_set]
    if missing:
        raise ValueError(f"Digests for files {missing} are not used")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    def _parse_version(v):
        parts = v.split('.')
        parsed = []
        for p in parts:
            if p.isdigit():
                parsed.append(int(p))
            else:
                # handle alphanumeric suffixes like '1a1'
                num = ''
                rest = ''
                for ch in p:
                    if ch.isdigit():
                        num += ch
                    else:
                        rest += ch
                if num:
                    parsed.append(int(num))
                if rest:
                    parsed.append(rest)
        return tuple(parsed)

    target = _parse_version(version)
    result = {}
    for logical_path, data in inventory.items():
        if not isinstance(data, dict):
            continue
        # Expect data to be a mapping of version -> content_file
        content_files = set()
        for ver, content_file in data.items():
            if not isinstance(ver, str) or not isinstance(content_file, str):
                continue
            try:
                ver_parsed = _parse_version(ver)
            except Exception:
                continue
            if ver_parsed >= target:
                content_files.add(content_file)
        if content_files:
            result[logical_path] = content_files
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise ValueError("manifest_files must be a set or list")
    manifest_set = set(manifest_files)
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if 'path' not in entry:
            raise ValueError("File entry missing 'path' key")
        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"File '{path}' in fixity block not found in manifest")
    return True

def files_list(path):
    """Return the files in `path`"""
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [
            os.path.abspath(os.path.join(path, f))
            for f in os.listdir(path)
            if os.path.isfile(os.path.join(path, f))
        ]
    return []

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """

    # Helper to create a single asset and return its id
    def _create_asset(name, path):
        if not os.path.isfile(path):
            raise FileNotFoundError(f"File not found: {path}")
        try:
            mgr = self._get_provider_manager('REPOSITORY')
            create_form = mgr.get_asset_form_for_create()
            create_form.set_name(name)
            create_form.set_file(path)
            asset = mgr.create_asset(create_form)
            return asset.get_id()
        except Exception as exc:
            raise RuntimeError(f"Failed to create asset '{name}': {exc}") from exc

    # If file_path is a mapping of filenames to paths, create an asset for each
    if isinstance(file_path, dict):
        asset_ids = {}
        for fname, fpath in file_path.items():
            asset_ids[fname] = _create_asset(fname, fpath)
        return asset_ids

    # Otherwise treat file_path as a single file
    return {basename: _create_asset(basename, file_path)}

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Build a mapping from directory to all files in that directory
            dir_to_files = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                dir_path = os.path.dirname(info.filename)
                dir_to_files.setdefault(dir_path, []).append(info.filename)

            # Find all XML files and group files in the same directory
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    xml_basename = os.path.splitext(os.path.basename(info.filename))[0]
                    dir_path = os.path.dirname(info.filename)
                    files_in_dir = dir_to_files.get(dir_path, [])
                    group = {}
                    for fname in files_in_dir:
                        try:
                            group[fname] = zf.read(fname)
                        except KeyError:
                            # Skip missing files
                            continue
                    result[xml_basename] = group
    except (FileNotFoundError, zipfile.BadZipFile):
        # Return empty dict if the zip file cannot be read
        return {}
    return result

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError("Error processing content") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non-negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")
    try:
        import pprint
        formatted = pprint.pformat(self, indent=indent)
    except Exception:
        try:
            formatted = str(self)
        except Exception:
            formatted = repr(self)
    if debug:
        try:
            type_name = type(self).__name__
            return f"{type_name}:\n{formatted}"
        except Exception:
            return formatted
    return formatted

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.

        """
        if hook is None:
            raise ValueError("hook must not be None")
        def decorator(fn):
            if not callable(fn):
                raise TypeError("handler must be callable")
            try:
                self.register_hook(hook, fn)
            except Exception as exc:
                raise RuntimeError(f"Failed to register handler for hook {hook}") from exc
