def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        if not isinstance(pieces, (list, tuple)):
            raise TypeError("pieces must be a list or tuple")
        if style not in ('json', 'csv', 'html', 'plain'):
            raise ValueError(f"Unsupported style: {style}")

        if style == 'json':
            # Simple JSON array representation without importing json
            json_parts = []
            for p in pieces:
                if isinstance(p, str):
                    escaped = p.replace('"', '\\"')
                    json_parts.append(f'"{escaped}"')
                else:
                    json_parts.append(str(p))
            return '[' + ', '.join(json_parts) + ']'

        elif style == 'csv':
            return ','.join(str(p) for p in pieces)

        elif style == 'html':
            return '<ul>' + ''.join(f'<li>{p}</li>' for p in pieces) + '</ul>'

