def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Build the command list
    if isinstance(commands, list):
        cmd_list = list(commands)
    elif isinstance(commands, str):
        cmd_list = [commands]
    else:
        raise TypeError("commands must be a list or a string")

    if args:
        if not isinstance(args, list):
            raise TypeError("args must be a list of strings")
        cmd_list.extend(args)

    # Validate that all elements are strings
    if not all(isinstance(part, str) for part in cmd_list):
        raise ValueError("All command parts must be strings")

    # Prepare environment
    env_dict = os.environ.copy()
    if env:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_dict.update(env)

    # Verbose output
    if verbose:
        print("Running command:", " ".join(cmd_list))

    # Execute the command
    try:
        stderr = subprocess.DEVNULL if hide_stderr else None
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env_dict,
            stderr=stderr,
            shell=False
        )
        return output.decode('utf-8')
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{' '.join(cmd_list)}' failed with exit code {e.returncode}") from e
    except OSError as e:
        raise RuntimeError(f"Execution failed: {e}") from e

