def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError as exc:
                    raise TypeError(f"Cannot sum values for key {key!r}") from exc
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    import re
    from urllib.parse import quote

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            try:
                return quote(str(url_args[key]), safe='')
            except Exception:
                return str(url_args[key])
        return match.group(0)

    try:
        return re.sub(r'\{([^}]+)\}', _repl, url)
    except Exception:
        return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings can represent a None value in textual form
    if isinstance(val, str):
        stripped = val.strip()
        # Empty string or common textual null representations
        if not stripped:
            return True
        lowered = stripped.lower()
        if lowered in ("none", "null", "undefined"):
            return True
    return False

