    '''
    try:
        try:
            verts = list(vertices)
        except TypeError:
            raise TypeError("vertices must be an iterable")
        n = len(verts)
        if n < 3:
            raise ValueError("At least 3 vertices required")
        result = []
        for i in range(n):
            prev = verts[(i - 1) % n]
            curr = verts[i]
            nxt = verts[(i + 1) % n]
            result.append((prev, curr, nxt))
        return result
    except Exception as e:
        raise e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("all elements of alphabet must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique symbols")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and padding > len(result):
        pad_char = alphabet[0]
        result = pad_char * (padding - len(result)) + result

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if value is None:
        raise ValueError("value cannot be None")
    if arg is None:
        raise ValueError("arg cannot be None")
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        try:
            subcls = current.__subclasses__()
        except Exception:
            continue
        for sub in subcls:
            if sub not in seen:
                seen.add(sub)
                queue.append(sub)
    return seen

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # Fallback for systems where os.uname() is not available
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    try:
        # Remove matching outer quotes (single or double)
        if len(name) > 1 and name[0] == name[-1] and name[0] in ("'", '"'):
            return name[1:-1]
        return name
    except Exception:
        return name

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            capture_output=True,
            text=True,
            check=True
        )
        files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
        files.sort()
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git is not available or the command fails, return an empty string
        return ''

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        for info in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = info
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        return False
    return False

