@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Retrieve the mapping of protocol versions to handler classes.
        # Subclasses may override this attribute; default to an empty dict.
        handlers = getattr(cls, "PROTOCOL_HANDLERS", {})
        if not isinstance(handlers, dict):
            # If the attribute exists but is not a dict, treat as unsupported.
            handlers = {}

        if protocol_version is None:
            # Return a shallow copy to prevent accidental mutation.
            return dict(handlers)

        # Return a single-item dict if the requested version is supported,
        # otherwise an empty dict.
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError(f"values must be an iterable, got {type(values).__name__}")

    bookmarks = []
    for raw in iterator:
        if not isinstance(raw, str):
            raise TypeError(f"bookmark value must be a string, got {type(raw).__name__}")
        try:
            bookmark = Bookmark.from_raw_value(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark value '{raw}': {exc}") from exc
        bookmarks.append(bookmark)

    return cls(bookmarks=bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Validate bufsize
    if bufsize is not None:
        if not isinstance(bufsize, int) or bufsize <= 0:
            raise ValueError("bufsize must be a positive integer")
    # If seq is a string or bytes, return it unchanged
    if isinstance(seq, (str, bytes)):
        return (seq, 'string')
    # If seq is already a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return (seq, 'list')
    # Try to convert seq to a list
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError("seq must be a sequence or iterable")
    # If a buffer size is requested, chunk the list into sublists
    if bufsize is not None:
        seq_list = [seq_list[i:i + bufsize] for i in range(0, len(seq_list), bufsize)]
    return (seq_list, 'list')

