def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache has items
    if not getattr(self, "_data", {}):
        raise KeyError("cache is empty")

    # Retrieve the frequency mapping; if it doesn't exist, treat as empty
    freq_map = getattr(self, "_freq", {})
    if not freq_map:
        raise KeyError("cache is empty")

    # Find the key with the lowest frequency count
    try:
        min_key = min(freq_map, key=lambda k: freq_map[k])
    except ValueError:
        raise KeyError("cache is empty")

    # Remove the key from the data store and frequency map
    value = self._data.pop(min_key)
    freq_map.pop(min_key, None)

    # If there is an auxiliary structure that tracks keys by frequency,
    # update it here (optional, depends on implementation).
    if hasattr(self, "_freq_buckets"):
        bucket = freq_map.get(min_key, None)
        if bucket is not None:
            self._freq_buckets[bucket].discard(min_key)
            if not self._freq_buckets[bucket]:
                del self._freq_buckets[bucket]

    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return dict.popitem(self)
    except KeyError:
        raise KeyError('dict is empty')

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dict is empty')
    try:
        import random
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except AttributeError:
        raise TypeError('popitem requires a dict-like object')
    except Exception as e:
        raise e

