    """Format a datetime in the way that D* nodes expect."""
    try:
        if not hasattr(dt, "astimezone"):
            raise TypeError("dt must be a datetime instance")
        # Ensure the datetime is timezone-aware; assume UTC if naive
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        # Convert to UTC and format as ISO 8601 with trailing 'Z'
        utc_dt = dt.astimezone(datetime.timezone.utc)
        return utc_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as exc:
        raise ValueError(f"Invalid datetime input: {exc}") from exc

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return text
    try:
        import re
        # Regular expression to match HTTP/HTTPS URLs
        url_re = re.compile(r'(https?://[^\s]+)')
        def replace(match):
            url = match.group(0)
            # Add desired attributes to the link
            return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
        return url_re.sub(replace, text)
    except Exception:
        # In case of any unexpected error, return the original text unchanged
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        if not url:
            return None
        parsed = urllib.parse.urlsplit(url)
        if parsed.scheme not in ('http', 'https'):
            return None
        req = urllib.request.Request(url)
        # Ensure the request uses the HEAD method
        if hasattr(req, 'method'):
            req.method = 'HEAD'
        else:
            req.get_method = lambda: 'HEAD'
        with urllib.request.urlopen(req, timeout=10) as resp:
            if hasattr(resp, 'status') and resp.status >= 400:
                return None
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            raise TypeError("'tag' must be a string")
        tag = tag.strip()
        if not tag:
            return False
        # Allowed characters: letters, digits, underscore, hyphen
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        if not pattern.match(tag):
            return False
        # Optional length constraint (e.g., max 30 characters)
        if len(tag) > 30:
            return False
        return True
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not isinstance(url, str) or not url:
            raise ValueError("url must be a non-empty string")
        # Ensure the URL has a scheme
        if not (url.startswith("http://") or url.startswith("https://")):
            raise ValueError("url must start with http:// or https://")
        base_url = url.rstrip("/")
        if document_path is None:
            document_path = "/.well-known/nodeinfo"
        else:
            if not isinstance(document_path, str):
                raise TypeError("document_path must be a string")
            if not document_path.startswith("/"):
                document_path = "/" + document_path
        href = f"{base_url}{document_path}"
        return {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                    "href": href
                }
            ]
        }
    except Exception as exc:
        # Log the exception if a logger is available, otherwise ignore
        try:
            logger.warning("get_nodeinfo_well_known_document: %s", exc)
        except NameError:
            pass
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        return None
    try:
        import json
        data = json.loads(document)
        # New JSON format
        result = {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "links": data.get("links", []),
        }
        return result
    except Exception:
        # Try XRD (XML) format
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            # Helper to find elements with or without namespace
            def find(tag):
                return root.find(tag) or root.find(f"xrd:{tag}", ns)
            def findall(tag):
                return root.findall(tag) or root.findall(f"xrd:{tag}", ns)
            subject_el = find("Subject")
            subject = subject_el.text if subject_el is not None else None
            aliases = [el.text for el in findall("Alias") if el is not None]
            links = []
            for link_el in findall("Link"):
                if link_el is not None:
                    rel = link_el.attrib.get("rel")
                    href = link_el.attrib.get("href")
                    if rel and href:
                        links.append({"rel": rel, "href": href})
            result = {
                "subject": subject,
                "aliases": aliases,
                "links": links,
            }
            return result
        except Exception:
            return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)

        matched_files = []
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                # If spec_option is None, match all files
                if spec_option is None or fnmatch.fnmatch(fname, spec_option):
                    matched_files.append(os.path.join(directory, fname))

        return sorted(matched_files)
    except Exception:
        # In case of any error (e.g., permission issues), return an empty list
        return []

