def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}") from e
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")
    required = getattr(cls, "required_fields", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Helper to merge actions from an included parser into the target parser.
    def _merge_actions(target, source, visited):
        if source in visited:
            return
        visited.add(source)
        for action in getattr(source, "_actions", []):
            # Skip the default help action to avoid duplicate help entries.
            if action.dest == "help":
                continue
            # Avoid adding duplicate destinations.
            if any(a.dest == action.dest for a in getattr(target, "_actions", [])):
                continue
            # Use the private method to add the action to the target parser.
            target._add_action(action)
        # Recursively handle nested includes.
        nested = getattr(source, "include", None)
        if nested:
            for name in nested:
                if name not in parser_dict:
                    raise KeyError(f"Included parser '{name}' not found in parser_dict")
                _merge_actions(target, parser_dict[name], visited)

    # Iterate over all parsers and process their include directives.
    for name, parser in parser_dict.items():
        includes = getattr(parser, "include", None)
        if includes:
            visited = set()
            for inc_name in includes:
                if inc_name not in parser_dict:
                    raise KeyError(f"Included parser '{inc_name}' not found in parser_dict")
                _merge_actions(parser, parser_dict[inc_name], visited)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # If no spec provided, just return defaults from args
    spec = getattr(self, 'spec', None)
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to resolve default for non-Option type')
        # Prefer value from spec if present
        if spec is not None and isinstance(spec, dict) and arg.name in spec:
            val = spec[arg.name]
            defaults[arg.name] = val
        else:
            # Fallback to the option's own default if it exists
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default
        # Handle nested dict options
        if isinstance(arg, DictOption):
            # If the option has a nested scheme, merge its defaults
            if arg.scheme:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Mapping of deprecated argument names to their current replacements.
    # Update this dictionary as new deprecations are introduced.
    return {
        "old_option": "new_option",
        "legacy_flag": "modern_flag",
        "deprecated_mode": "mode",
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure the inputs are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve the mapping of deprecated to current argument names.
    # If the mapping is not defined or not a dict, nothing to validate.
    deprecated_map = getattr(self, "deprecated_args", None)
    if not isinstance(deprecated_map, dict):
        return

    # Combine the arguments, giving precedence to CLI over answer file.
    combined_args = {}
    combined_args.update(answer_file_args)
    combined_args.update(cli_args)

    # Check each deprecated argument.
    for old_name, new_name in deprecated_map.items():
        if old_name in combined_args:
            # Determine where the deprecated argument came from.
            source = None
            if old_name in cli_args:
                source = "CLI"
            elif old_name in answer_file_args:
                source = "answer file"
            else:
                source = "unknown source"

            warning_msg = (
                f"Deprecated argument '{old_name}' detected in {source}. "
                f"Use '{new_name}' instead."
            )
            try:
                # Prefer printing to the console; fall back to warnings if printing fails.
                print(warning_msg)
            except Exception:
                import warnings
                warnings.warn(warning_msg, DeprecationWarning, stacklevel=2)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if command_name is None:
        raise TypeError("command_name must not be None")
    # The command options are expected to be stored in a mapping
    # attribute of the instance.  Use a safe lookup and provide a
    # clear error message if the command is unknown.
    try:
        options = getattr(self, "_command_options", {}).get(command_name)
    except Exception as exc:
        raise RuntimeError("Failed to access command options mapping") from exc
    if options is None:
        raise ValueError(f"Unknown command name: {command_name!r}")
    # Ensure a mutable list is returned so callers can modify it
    # without affecting the internal state.
    return list(options)

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    try:
        for arg in args:
            if isinstance(arg, str) and arg.startswith('-'):
                # ignore a lone '--'
                if arg == '--':
                    continue
                # strip leading dashes
                name = arg.lstrip('-')
                if name:
                    silent.append(name)
    except TypeError:
        # args is not iterable
        return []
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    # Retrieve required arguments list
    required = getattr(self, 'required_args', None)
    if required is None:
        required = getattr(self, '_required_args', None)
    if required is None:
        # No required arguments defined; nothing to validate
        return
    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError("required_args must be an iterable of argument names")
    # Find missing or None-valued required arguments
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Skip if no required_when attribute
        cond = getattr(opt, 'required_when', None)
        if cond is None:
            continue
        try:
            # If condition is callable, call it with args
            if callable(cond):
                if cond(args):
                    required.append(opt.name)
            # If condition is a string, evaluate it in a safe namespace
            elif isinstance(cond, str):
                # Provide args in the local namespace for evaluation
                if eval(cond, {}, {'args': args}):
                    required.append(opt.name)
        except Exception:
            # Ignore any errors in evaluating the condition
            continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict (got %s)" % type(args).__name__)

    # Retrieve the argument specifications from the parsed YAML
    arg_specs = self.parsed_yaml.get('args', {})

    for arg_name, value in args.items():
        # Skip arguments that have no specification
        spec = arg_specs.get(arg_name)
        if spec is None:
            continue

        # Get the maximum allowed length for this argument
        max_len = spec.get('length')
        if max_len is None:
            continue

        if not isinstance(max_len, int):
            raise TypeError(
                "length for argument '%s' must be an integer (got %s)"
                % (arg_name, type(max_len).__name__)
            )
        if max_len < 0:
            raise ValueError(
                "length for argument '%s' must be non‑negative (got %d)"
                % (arg_name, max_len)
            )

        # Skip validation if the value is None
        if value is None:
            continue

        # Attempt to determine the length of the value
        try:
            val_len = len(value)
        except TypeError:
            # If the value has no length, we cannot validate it
            continue

        if val_len > max_len:
            raise ValueError(
                "argument '%s' length %d exceeds maximum allowed %d"
                % (arg_name, val_len, max_len)
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict, got %s" % type(args).__name__)

    # Retrieve the argument definitions that may contain 'choices' metadata.
    arg_defs = getattr(self, 'arg_definitions', {})
    if not isinstance(arg_defs, dict):
        raise TypeError("self.arg_definitions must be a dict, got %s" % type(arg_defs).__name__)

    for arg_name, value in args.items():
        arg_def = arg_defs.get(arg_name)
        if not arg_def:
            # No definition for this argument; skip validation.
            continue

        choices = arg_def.get('choices')
        if choices is None:
            # Argument has no defined choices; skip validation.
            continue

        # Ensure choices is an iterable of allowed values.
        try:
            allowed = set(choices)
        except TypeError:
            raise ValueError("choices for argument '%s' must be an iterable" % arg_name)

        # Handle multiple values (e.g., list, tuple, set) separately.
        if isinstance(value, (list, tuple, set)):
            invalid = [v for v in value if v not in allowed]
            if invalid:
                raise ValueError(
                    "Invalid value(s) for argument '%s': %s. "
                    "Allowed choices are: %s" % (arg_name, invalid, sorted(allowed))
                )
        else:
            if value not in allowed:
                raise ValueError(
                    "Invalid value for argument '%s': %s. "
                    "Allowed choices are: %s" % (arg_name, value, sorted(allowed))
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the object has min and max attributes
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Object must have 'min' and 'max' attributes")
    min_val = self.min
    max_val = self.max

    # Validate that min and max are consistent
    if min_val is not None and max_val is not None and min_val > max_val:
        raise ValueError("minimum value must be less than or equal to maximum value")

    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable")

    # If args is a dict, iterate over its values
    values = args.values() if isinstance(args, dict) else args

    for idx, val in enumerate(values):
        if val is None:
            raise ValueError(f"argument at position {idx} is None, expected a value between {min_val} and {max_val}")

        try:
            if min_val is not None and val < min_val:
                raise ValueError(f"argument {val} at position {idx} is less than minimum {min_val}")
            if max_val is not None and val > max_val:
                raise ValueError(f"argument {val} at position {idx} is greater than maximum {max_val}")
        except TypeError:
            raise TypeError(f"argument {val} at position {idx} is not comparable to min/max values")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str) or not subcommand:
        raise ValueError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise ValueError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dictionary")

    # Extract parsing configuration from spec_option
    pair_separator = spec_option.get("pair_separator", ",")
    key_value_separator = spec_option.get("key_value_separator", "=")
    required_keys = set(spec_option.get("required_keys", []))

    def _parse_complex(value):
        """Parse a complex option string into a dictionary."""
        if not isinstance(value, str):
            raise TypeError(
                f"Expected a string for option '{option_name}', got {type(value).__name__}"
            )
        try:
            # Split into key/value pairs
            pairs = [p.strip() for p in value.split(pair_separator) if p.strip()]
            result = {}
            for pair in pairs:
                if key_value_separator not in pair:
                    raise ValueError(
                        f"Invalid pair '{pair}' for option '{option_name}'; "
                        f"expected separator '{key_value_separator}'"
                    )
                key, val = pair.split(key_value_separator, 1)
                key = key.strip()
                val = val.strip()
                if not key:
                    raise ValueError(
                        f"Empty key in pair '{pair}' for option '{option_name}'"
                    )
                result[key] = val

            # Validate required keys
            if required_keys and not required_keys.issubset(result.keys()):
                missing = required_keys - result.keys()
                raise ValueError(
                    f"Missing required keys {missing} in option '{option_name}'"
                )
            return result
        except Exception as exc:
            # Re‑raise with a clearer message
            raise ValueError(
                f"Failed to parse complex option '{option_name}': {exc}"
            ) from exc

    # Attach helpful metadata
    _parse_complex.__name__ = f"{type_name}_{option_name}_parser"
    _parse_complex.__doc__ = (
        f"Parser for complex option '{option_name}' of subcommand '{subcommand}'"
    )
    return _parse_complex

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        try:
            vars_dict.update(extra_vars)
        except Exception as e:
            raise ValueError(f"Failed to merge dict: {e}") from e
        return vars_dict
    if isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                try:
                    vars_dict.update(item)
                except Exception as e:
                    raise ValueError(f"Failed to merge dict item: {e}") from e
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                vars_dict[key] = value
            elif isinstance(item, str):
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                else:
                    raise ValueError(f"Invalid string format for extra_vars item: {item}")
            else:
                raise ValueError(f"Unsupported extra_vars item type: {type(item)}")
        return vars_dict
    raise TypeError("extra_vars must be a dict or list")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import json

    # Resolve absolute path if necessary
    if not os.path.isabs(playbook_path):
        # Assume workspace has a 'path' attribute pointing to its root
        base_path = getattr(ir_workspace, "path", "")
        playbook_path = os.path.join(base_path, playbook_path)

    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist")

    command = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                command.append("-" + "v" * verbose)
        else:
            # Assume string like "-vvv" or "--verbose"
            command.append(str(verbose))

    # Handle ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
            else:
                command.append(f"--{key}={value}")

    # Handle extra-vars
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars)
        except Exception:
            # Fallback to key=value pairs
            json_vars = " ".join(f"{k}={v}" for k, v in extra_vars.items())
        command.extend(["--extra-vars", json_vars])

    # Execute the command
    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Ansible playbook failed with exit code {exc.returncode}:\n{exc.stderr}"
        ) from exc

    return result.stdout

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate input
    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        return {}

    # Determine spec file (JSON or YAML)
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        spec_path = os.path.join(plugin_dir, 'plugin.yaml')
        if not os.path.isfile(spec_path):
            return {}

    # Load spec data
    try:
        if spec_path.endswith('.json'):
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        else:
            import yaml
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
    except Exception:
        return {}

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data) if isinstance(data, dict) else {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    # Only set if the environment variable is not already defined
    if os.getenv(env_var) is None:
        # Ensure the instance has a config_path attribute
        if not hasattr(self, 'config_path'):
            raise AttributeError("Instance has no 'config_path' attribute")
        # Validate the config_path value
        config_path = self.config_path
        if config_path is None:
            raise ValueError("config_path is None; cannot set environment variable")
        # Convert to string if it's a Path-like object
        try:
            config_path_str = str(config_path)
        except Exception as exc:
            raise ValueError(f"config_path could not be converted to string: {exc}") from exc
        os.environ[env_var] = config_path_str
        return config_path_str
    # If already set, simply return the existing value
    return os.getenv(env_var)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    if root == "":
        raise ValueError("Root cannot be an empty string")
    abs_path = os.path.abspath(path)
    abs_root = os.path.abspath(root)
    try:
        common = os.path.commonpath([abs_path, abs_root])
    except ValueError:
        # Different drives on Windows or other path issues
        raise ValueError(f"Root '{root}' is not a parent of path '{path}'")
    if common != abs_root:
        raise ValueError(f"Root '{root}' is not a parent of path '{path}'")
    # Remove the root prefix
    stripped = abs_path[len(abs_root):]
    # Strip a leading separator if present
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]
    return stripped
